"""Multi-currency account ledger.

Accounts hold one balance per supported currency (USD, EUR, JPY).
Balances are ``decimal.Decimal`` values quantized to the currency's
decimal places (2 for USD/EUR, 0 for JPY) after every operation.
"""

from __future__ import annotations

from decimal import Decimal

from money import check_currency, require_positive, quantize, to_decimal

_DEFAULT_CURRENCY = "USD"


def _money(amount, name="amount"):
    """Coerce and quantize an opening balance (zero allowed, negative not)."""
    return quantize(to_decimal(amount, name), _DEFAULT_CURRENCY)


class Account:
    """An account holding balances in each supported currency."""

    def __init__(self, owner, balance=0.0):
        if not owner:
            raise ValueError("owner must be a non-empty string")
        opening = _money(balance, "balance")
        if opening < 0:
            raise ValueError("opening balance must be >= 0")
        self.owner = owner
        self._balances = {_DEFAULT_CURRENCY: opening}

    @property
    def balance(self):
        """Current USD balance as a Decimal (0.00 if none stored)."""
        return self._balances.get(_DEFAULT_CURRENCY, quantize(Decimal(0), _DEFAULT_CURRENCY))

    @property
    def balances(self):
        """Copy of the per-currency balances, {currency: Decimal}."""
        return dict(self._balances)

    def _move(self, amount, currency, credit):
        """Apply a quantized, validated amount; returns the new balance."""
        moved = require_positive(quantize(to_decimal(amount, "amount"), currency), "amount")
        current = self._balances.get(currency, quantize(Decimal(0), currency))
        new_balance = quantize(current + moved if credit else current - moved, currency)
        if new_balance < 0:
            raise ValueError("insufficient funds")
        self._balances[currency] = new_balance
        return new_balance

    def deposit(self, amount, currency=_DEFAULT_CURRENCY):
        """Add funds in a currency; returns the new balance for it."""
        check_currency(currency)
        return self._move(amount, currency, credit=True)

    def withdraw(self, amount, currency=_DEFAULT_CURRENCY):
        """Remove funds in a currency; returns the new balance for it."""
        check_currency(currency)
        return self._move(amount, currency, credit=False)

    def to_dict(self):
        """Serialize to the version-2 record schema."""
        return {
            "owner": self.owner,
            "balances": {cur: str(value) for cur, value in self._balances.items()},
        }

    @classmethod
    def from_dict(cls, data):
        """Rebuild an account from a version-2 record."""
        owner = data["owner"]
        if not owner:
            raise ValueError("owner must be a non-empty string")
        instance = cls.__new__(cls)
        instance.owner = owner
        instance._balances = {}
        for currency, raw in data.get("balances", {}).items():
            check_currency(currency)
            instance._balances[currency] = quantize(to_decimal(raw, "balance"), currency)
        return instance

    def __eq__(self, other):
        if not isinstance(other, Account):
            return NotImplemented
        return self.owner == other.owner and self._balances == other._balances

    def __repr__(self):
        return "Account(owner=%r, balances=%r)" % (self.owner, self._balances)


def transfer(source, target, amount, currency=_DEFAULT_CURRENCY):
    """Move funds between two accounts in a currency; returns the amount moved."""
    check_currency(currency)
    moved = require_positive(quantize(to_decimal(amount, "amount"), currency), "amount")
    source.withdraw(moved, currency)
    target.deposit(moved, currency)
    return moved

finished.money.py:
"""Shared money rules for the ledger.

One consistent money concept used by accounts, fees, report and store:

* Exactly three supported currencies: USD, EUR, JPY.
* Money is stored and returned as ``decimal.Decimal``.
* Amounts are quantized ROUND_HALF_UP to 2 decimal places for USD/EUR
  and 0 decimal places for JPY.
* Order is convert -> quantize -> validate: a quantized amount that is
  not positive raises ``ValueError``.
"""

from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP

SUPPORTED_CURRENCIES = ("USD", "EUR", "JPY")

_DECIMAL_PLACES = {"USD": 2, "EUR": 2, "JPY": 0}

# Pinned conversion rates; cross rates route through USD, applied left
# to right at default Decimal precision:
#   1 EUR = 1.08 USD, 1 USD = 155 JPY
#   EUR -> JPY: multiply by 1.08 then by 155
#   JPY -> EUR: divide by 155 then by 1.08
_RATES = {
    ("USD", "USD"): Decimal(1),
    ("USD", "EUR"): Decimal(1) / Decimal("1.08"),
    ("USD", "JPY"): Decimal(155),
    ("EUR", "USD"): Decimal("1.08"),
    ("EUR", "JPY"): Decimal("1.08") * Decimal(155),
    ("JPY", "USD"): Decimal(1) / Decimal(155),
    ("JPY", "EUR"): (Decimal(1) / Decimal(155)) / Decimal("1.08"),
}


def _currency_error(name, value):
    return ValueError(
        "unsupported currency %r: supported currencies are %s"
        % (value, ", ".join(SUPPORTED_CURRENCIES))
    )


def check_currency(currency):
    """Validate a currency code; returns it unchanged."""
    if not isinstance(currency, str) or currency not in SUPPORTED_CURRENCIES:
        raise _currency_error("currency", currency)
    return currency


def to_decimal(value, name="amount"):
    """Coerce an amount to a Decimal.

    Accepts int, str, float and Decimal. Floats are converted via
    ``Decimal(str(value))``. Any other type raises ``TypeError``.
    """
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(str(value))
    if isinstance(value, int) and not isinstance(value, bool):
        return Decimal(value)
    if isinstance(value, str):
        try:
            return Decimal(value)
        except Exception:
            raise ValueError("invalid %s: %r" % (name, value))
    raise TypeError("%s must be int, str, float or Decimal, got %r" % (name, type(value).__name__))


def quantize(amount, currency):
    """Quantize a Decimal amount to the currency's decimal places."""
    check_currency(currency)
    return amount.quantize(Decimal(1).scaleb(-_DECIMAL_PLACES[currency]), rounding=ROUND_HALF_UP)


def require_positive(amount, currency, name="amount"):
    """Validate a quantized amount; a non-positive value raises ValueError."""
    if amount <= 0:
        raise ValueError("%s must be positive, got %s" % (name, amount))
    return amount


def convert(amount, source, target):
    """Convert a Decimal amount between supported currencies."""
    check_currency(source)
    check_currency(target)
    if source == target:
        return amount
    return amount * _RATES[(source, target)]

finished.store.py:
"""JSON persistence for multi-currency accounts.

On-disk schema (version 2):

    {"version": 2, "accounts": [{"owner": str,
     "balances": {currency: "decimal-string"}}]}

Each Decimal is encoded via str() (e.g. "10.00", "500"). Old
version-1 files ({"version": 1, "accounts": [{"owner", "balance":
number}]}, where a missing "version" also means 1) are still read,
mapping the old balance number to USD.
"""

from __future__ import annotations

import json

from accounts import Account

SCHEMA_VERSION = 2


def _to_record(account):
    """Serialize one account to its version-2 storage record."""
    return {
        "owner": account.owner,
        "balances": {cur: str(value) for cur, value in account.balances.items()},
    }


def _from_record(record):
    """Rebuild one account from a version-2 storage record."""
    return Account.from_dict(record)


def save_accounts(accounts, path):
    """Write accounts to path as version-2 JSON. Returns the path."""
    payload = {
        "version": SCHEMA_VERSION,
        "accounts": [_to_record(acc) for acc in accounts],
    }
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2, sort_keys=True)
    return path


def append_account(account, path):
    """Append one account to the JSON file at path.

    Creates a new version-2 file when none exists yet.
    """
    try:
        accounts = load_accounts(path)
    except FileNotFoundError:
        accounts = []
    accounts.append(account)
    save_accounts(accounts, path)
    return account


def load_accounts(path):
    """Read accounts back from a version-2 (or legacy version-1) JSON file."""
    with open(path, encoding="utf-8") as handle:
        payload = json.load(handle)
    version = payload.get("version", 1)
    if version == 2:
        return [_from_record(record) for record in payload.get("accounts", [])]
    if version == 1:
        return [
            Account(record["owner"], record.get("balance", 0.0))
            for record in payload.get("accounts", [])
        ]
    raise ValueError("unsupported schema version: %r" % (version,))

